// Runs inside the compiled test program generated by tool/src/test_build.dart.
// One process tests one (problem, solution) pair and prints a single result line:
//   @@DSA-RESULT {json}
import 'dart:convert';
import 'dart:io';

import '../testing.dart';

/// A solution wired to its problem's suite by generated code.
class Entry {
  final Suite suite;

  /// Fingerprints from expected.json (empty when recording or when the suite uses [Suite.check]).
  final List<String> expected;

  /// Typed deep copies of a case's arguments (not timed).
  final List<Object?> Function(List<Object?> args) prepare;

  /// Calls the solution with prepared arguments and returns its return value.
  final Object? Function(List<Object?> prepared) call;

  Entry(this.suite, this.expected, this.prepare, this.call);
}

const resultMarker = '@@DSA-RESULT ';

/// args: `<entry id> [--record] [--verbose] [--small-only]`
void runEntry(Map<String, Entry> entries, List<String> args) {
  final entry = entries[args.first]!;
  final record = args.contains('--record');
  final verbose = args.contains('--verbose');
  final smallOnly = args.contains('--small-only');
  final suite = entry.suite;

  final cases = suite.cases(Gen(suite.seed));
  if (!record && suite.check == null && entry.expected.length != cases.length) {
    _emit({'status': 'error', 'message': 'expected.json is out of date (${entry.expected.length} answers for ${cases.length} cases)'});
    return;
  }
  // Extra memory = growth of the peak RSS during a large case's first call (inputs already built),
  // the largest across large cases. Small cases are too small to matter.
  var extraBytes = 0;

  final hashes = <String>[];
  final caseTimes = <int>[];
  var passed = 0;
  var smallFailed = false;
  Map<String, Object?>? failure;

  Object? answerOf(List<Object?> prepared, Object? returned) =>
      suite.resultArg == null ? returned : prepared[suite.resultArg!];

  for (var i = 0; i < cases.length; i++) {
    final c = cases[i];
    if (c.large && smallFailed && !record) break;
    if (c.large && smallOnly) {
      hashes.add('');
      continue;
    }

    final runs = c.large ? 3 : 1;
    final times = <int>[];
    Object? answer;
    for (var run = 0; run < runs + (c.large ? 1 : 0); run++) {
      final prepared = entry.prepare(c.args);
      final peakBefore = c.large && run == 0 ? ProcessInfo.maxRss : 0;
      final sw = Stopwatch()..start();
      Object? returned;
      try {
        returned = entry.call(prepared);
      } on UnimplementedError {
        _emit({'status': 'unimplemented', 'passed': passed, 'total': cases.length});
        return;
      } catch (e, st) {
        _emit({
          'status': 'error',
          'case': i,
          'passed': passed,
          'total': cases.length,
          'message': _short('$e'),
          if (verbose) 'input': _short(canonical(c.args), 400),
          if (verbose) 'stack': _short(_userFrames(st), 600),
        });
        return;
      }
      sw.stop();
      if (c.large && run == 0) {
        final grew = ProcessInfo.maxRss - peakBefore;
        if (grew > extraBytes) extraBytes = grew;
        // Warm-up run (not counted). If it is already slow, don't repeat it many times.
        if (sw.elapsedMilliseconds > 400) {
          times.add(sw.elapsedMicroseconds);
          answer = answerOf(prepared, returned);
          break;
        }
        continue;
      }
      times.add(sw.elapsedMicroseconds);
      answer = answerOf(prepared, returned);
    }
    times.sort();
    final median = times[times.length ~/ 2];
    if (c.large) caseTimes.add(median);

    final ok = record ? true : _isCorrect(entry, i, c, answer);
    if (record) {
      if (suite.check != null && !suite.check!(entry.prepare(c.args), answer)) {
        _emit({'status': 'error', 'case': i, 'message': 'reference answer rejected by the checker', 'output': _short(canonical(answer), 400)});
        return;
      }
      hashes.add(fingerprint(canonical(answer, unordered: suite.unordered)));
    }
    if (ok) {
      passed++;
    } else {
      if (!c.large) smallFailed = true;
      failure ??= {
        'case': i,
        'large': c.large,
        if (verbose) 'input': _short(canonical(c.args), 400),
        if (verbose) 'output': _short(canonical(answer, unordered: suite.unordered), 400),
      };
    }
  }

  final mem = extraBytes / (1 << 20);
  final timeUs = caseTimes.fold<int>(0, (a, b) => a + b);
  final status = failure != null
      ? 'fail'
      : mem > suite.memoryLimitMb
          ? 'memory'
          : 'pass';
  _emit({
    'status': status,
    'passed': passed,
    'total': cases.length,
    'timeUs': timeUs,
    'memoryMb': double.parse(mem.toStringAsFixed(1)),
    if (failure != null) 'failure': failure,
    if (record) 'hashes': hashes,
  });
}

bool _isCorrect(Entry entry, int i, Case c, Object? answer) {
  final suite = entry.suite;
  if (suite.check != null) {
    try {
      return suite.check!(entry.prepare(c.args), answer);
    } catch (_) {
      return false;
    }
  }
  return fingerprint(canonical(answer, unordered: suite.unordered)) == entry.expected[i];
}

/// Frames up to the generated adapter (the solution's own calls), without the harness below it.
String _userFrames(StackTrace st) => '$st'
    .split('\n')
    .takeWhile((l) => !l.contains('/dsa_test/'))
    .where((l) => l.trim().isNotEmpty)
    .join('\n');

String _short(String s, [int max = 300]) => s.length <= max ? s : '${s.substring(0, max)}… (${s.length} chars)';

void _emit(Map<String, Object?> result) {
  stdout.writeln('$resultMarker${jsonEncode(result)}');
}
